"""Request handling for the API."""

from collections.abc import Mapping
from typing import Any


def _validate_request(data: Any, client_id: Any) -> None:
    """Validate the inputs required to handle a request.

    Request payloads must be mapping-like objects, and a client identifier must
    be a non-empty string.  Type errors are kept separate from invalid values so
    callers can distinguish malformed input from a missing identifier.
    """
    if not isinstance(data, Mapping):
        raise TypeError("data must be a mapping")

    if not isinstance(client_id, str):
        raise TypeError("client_id must be a string")
    if not client_id.strip():
        raise ValueError("client_id must not be empty")


def handle_request(data: Any, client_id: str):
    """Validate, rate-limit, and process an incoming API request."""
    _validate_request(data, client_id)

    if not check_rate_limit(client_id):
        raise RuntimeError("rate limit exceeded")

    return process(data)

